// NULL-tolerant scan buffer for accountIncomeScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type accountIncomePreloadBuf struct {
	ID          sql.Null[uuid.UUID]
	HouseholdID sql.Null[uuid.UUID]
	JournalID   sql.Null[uuid.UUID]
	AccountID   sql.Null[uuid.UUID]
	OccurredAt  sql.Null[time.Time]
	AmountYen   sql.Null[int64]
	Description sql.Null[string]
	CreatedAt   sql.Null[time.Time]
}

// accountIncomeScanMapperNullable maps the preloaded accountIncome
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func accountIncomeScanMapperNullable(prefix string) scan.Mapper[*AccountIncome] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*AccountIncome, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *accountIncomePreloadBuf) any
		}
		targets := make([]target, 0, 8)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *accountIncomePreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *accountIncomePreloadBuf) any { return &b.HouseholdID }})
			case "journal_id":
				targets = append(targets, target{i, func(b *accountIncomePreloadBuf) any { return &b.JournalID }})
			case "account_id":
				targets = append(targets, target{i, func(b *accountIncomePreloadBuf) any { return &b.AccountID }})
			case "occurred_at":
				targets = append(targets, target{i, func(b *accountIncomePreloadBuf) any { return &b.OccurredAt }})
			case "amount_yen":
				targets = append(targets, target{i, func(b *accountIncomePreloadBuf) any { return &b.AmountYen }})
			case "description":
				targets = append(targets, target{i, func(b *accountIncomePreloadBuf) any { return &b.Description }})
			case "created_at":
				targets = append(targets, target{i, func(b *accountIncomePreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(accountIncomePreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*AccountIncome, error) {
				buf := link.(*accountIncomePreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.JournalID.Valid) &&
					!(buf.AccountID.Valid) &&
					!(buf.OccurredAt.Valid) &&
					!(buf.AmountYen.Valid) &&
					!(buf.Description.Valid) &&
					!(buf.CreatedAt.Valid) {
					return nil, nil
				}

				o := new(AccountIncome)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.JournalID.Valid {
					o.JournalID = buf.JournalID.V
				}
				if buf.AccountID.Valid {
					o.AccountID = buf.AccountID.V
				}
				if buf.OccurredAt.Valid {
					o.OccurredAt = buf.OccurredAt.V
				}
				if buf.AmountYen.Valid {
					o.AmountYen = buf.AmountYen.V
				}
				if buf.Description.Valid {
					o.Description = buf.Description.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				return o, nil
			}
	}
}

func (o *AccountIncome) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Account":
		rel, ok := retrieved.(*Account)
		if !ok {
			return fmt.Errorf("accountIncome cannot load %T as %q", retrieved, name)
		}

		o.R.Account = rel
		o.R.Loaded.Account = true

		if rel != nil {
			rel.R.AccountIncomes = AccountIncomeSlice{o}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("accountIncome cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.AccountIncomes = AccountIncomeSlice{o}
		}
		return nil
	case "Journal":
		rel, ok := retrieved.(*Journal)
		if !ok {
			return fmt.Errorf("accountIncome cannot load %T as %q", retrieved, name)
		}

		o.R.Journal = rel
		o.R.Loaded.Journal = true

		if rel != nil {
			rel.R.AccountIncome = o
			rel.R.Loaded.AccountIncome = true
		}
		return nil
	default:
		return fmt.Errorf("accountIncome has no relationship %q", name)
	}
}

