// LoadAccount loads the accountIncome's Account into the .R struct
func (o *AccountIncome) LoadAccount(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Account = nil
	o.R.Loaded.Account = false

	related, err := o.Account(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AccountIncomes = AccountIncomeSlice{o}

	o.R.Account = related
	o.R.Loaded.Account = true
	return nil
}

// LoadAccount loads the accountIncome's Account into the .R struct
func (os AccountIncomeSlice) LoadAccount(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	accounts, err := os.Account(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Account = nil
		o.R.Loaded.Account = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range accounts {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.AccountID == rel.ID) {
				continue
			}

			rel.R.AccountIncomes = append(rel.R.AccountIncomes, o)

			o.R.Account = rel
			break
		}
	}

	return nil
}

// LoadHousehold loads the accountIncome's Household into the .R struct
func (o *AccountIncome) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AccountIncomes = AccountIncomeSlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the accountIncome's Household into the .R struct
func (os AccountIncomeSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	accountIncomeByKey := make(map[uuid.UUID][]*AccountIncome, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		accountIncomeByKey[o.HouseholdID] = append(accountIncomeByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := accountIncomeByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.AccountIncomes = append(rel.R.AccountIncomes, o)

			o.R.Household = rel

		}
	}

	return nil
}

// LoadJournal loads the accountIncome's Journal into the .R struct
func (o *AccountIncome) LoadJournal(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Journal = nil
	o.R.Loaded.Journal = false

	related, err := o.Journal(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AccountIncome = o
	related.R.Loaded.AccountIncome = true

	o.R.Journal = related
	o.R.Loaded.Journal = true
	return nil
}

// LoadJournal loads the accountIncome's Journal into the .R struct
func (os AccountIncomeSlice) LoadJournal(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	journals, err := os.Journal(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Journal = nil
		o.R.Loaded.Journal = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	accountIncomeByKey := make(map[uuid.UUID][]*AccountIncome, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		accountIncomeByKey[o.JournalID] = append(accountIncomeByKey[o.JournalID], o)
	}

	for _, rel := range journals {

		owners, ok := accountIncomeByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Journal != nil {
				continue
			}

			rel.R.AccountIncome = o
			rel.R.Loaded.AccountIncome = true

			o.R.Journal = rel

		}
	}

	return nil
}

type accountIncomeJoins[Q dialect.Joinable] struct {
	typ       string
	Account   modAs[Q, accountColumns]
	Household modAs[Q, householdColumns]
	Journal   modAs[Q, journalColumns]
}

func (j accountIncomeJoins[Q]) aliasedAs(alias string) accountIncomeJoins[Q] {
	return buildAccountIncomeJoins[Q](buildAccountIncomeColumns(alias), j.typ)
}

func buildAccountIncomeJoins[Q dialect.Joinable](cols accountIncomeColumns, typ string) accountIncomeJoins[Q] {
	return accountIncomeJoins[Q]{
		typ: typ,
		Account: modAs[Q, accountColumns]{
			c: Accounts.Columns,
			f: func(to accountColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Accounts.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.AccountID),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Journal: modAs[Q, journalColumns]{
			c: Journals.Columns,
			f: func(to journalColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Journals.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.JournalID),
					))
				}

				return mods
			},
		},
	}
}
